{"command": "python -c "
import sqlparse
from sqlparse import sql
tests = [
    'foo = 1',
    \"foo = 'bar'\",
    'foo = bar',
    '1 = 1',
]
for t in tests:
    s = sqlparse.parse(t)[0]
    print('---', repr(t))
    print(len(s.tokens))
    for tok in s.tokens:
        print(' ', repr(tok))
        if tok.is_group:
            for tt in tok.tokens:
                print('    ', repr(tt))
"
"}

